package dk.stream.android;
import okhttp3.mockwebserver.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class CastStreamTest {
 @Test public void recognizesExtensionlessHlsDespiteGenericHeader()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setHeader("Content-Type","application/octet-stream").setBody("#EXTM3U\n#EXT-X-TARGETDURATION:6\n"));String url=server.url("/channel?token=keep").toString();CastStream stream=CastStream.resolve(url,true);assertEquals("application/x-mpegURL",stream.type);assertEquals(url,stream.url);}}
 @Test public void usesResponseMimeForExtensionlessDash()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setHeader("Content-Type","application/dash+xml; charset=utf-8").setBody("<MPD></MPD>"));assertEquals("application/dash+xml",CastStream.resolve(server.url("/channel").toString(),true).type);}}
 @Test public void prefersWorkingHlsForXtreamTs()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setBody("#EXTM3U\n#EXTINF:6,\nsegment.ts\n"));CastStream stream=CastStream.resolve(server.url("/live/user/password/123.ts?token=keep").toString(),true);assertEquals("application/x-mpegURL",stream.type);assertEquals("/live/user/password/123.m3u8?token=keep",server.takeRequest().getPath());assertTrue(stream.url.contains("123.m3u8?token=keep"));assertEquals(1,server.getRequestCount());}}
 @Test public void fallsBackToOriginalWhenProviderRejectsHls()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setResponseCode(404));server.enqueue(new MockResponse().setHeader("Content-Type","video/mp2t").setBody("transport stream"));String url=server.url("/live/u/p/123.ts").toString();CastStream stream=CastStream.resolve(url,true);assertEquals(url,stream.url);assertEquals("video/mp2t",stream.type);assertEquals(2,server.getRequestCount());}}
 @Test public void rejectsProviderErrorPageInsteadOfTreatingItAsHls()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setHeader("Content-Type","application/json").setBody("{\"error\":\"format unavailable\"}"));server.enqueue(new MockResponse().setHeader("Content-Type","video/mp2t").setBody("transport stream"));String url=server.url("/live/u/p/123.ts").toString();assertEquals(url,CastStream.resolve(url,true).url);assertEquals(2,server.getRequestCount());}}
 @Test public void neverRewritesOrdinaryTsOrOnDemandLinks()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setHeader("Content-Type","video/mp2t").setBody("video"));String url=server.url("/movie/u/p/123.ts").toString();assertEquals(url,CastStream.resolve(url,false).url);assertEquals(1,server.getRequestCount());}}
 @Test public void preservesOriginalUrlAcrossHttpRedirect()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setResponseCode(302).setHeader("Location",server.url("/temporary.m3u8")));server.enqueue(new MockResponse().setBody("#EXTM3U\n"));String url=server.url("/channel").toString();CastStream stream=CastStream.resolve(url,true);assertEquals(url,stream.url);assertEquals("application/x-mpegURL",stream.type);}}
 @Test public void stillLoadsKnownFilesWhenProbeIsNotAllowed()throws Exception{try(MockWebServer server=new MockWebServer()){server.enqueue(new MockResponse().setResponseCode(403));CastStream stream=CastStream.resolve(server.url("/movie.mp4").toString(),false);assertEquals("video/mp4",stream.type);}}
}
